{
  "title": "SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions",
  "overview": "Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response.",
  "deliverables": [
    "Answers to Questions 1–6, each under its required heading and in order.",
    "Show calculations and working for all parts of Question 3.",
    "Include IEEE-style citations for external sources and a reference list at the end."
  ],
  "format": {
    "length": "Each answer must be at most 150 words; Question 3 calculations and working, and the reference list, are excluded from the limit.",
    "structure": "Use the headings “Question 1” through “Question 6”, in order. Place the reference list at the end.",
    "other": "Submit one document; this is an individual assignment. State any assumptions. Give availability as percentages to two decimal places and downtime in hours to one decimal place."
  },
  "requirements": [
    {
      "id": "R1",
      "text": "Question 1: Identify the two most important quality attributes for CampusEats and justify each choice using the scenario. For each attribute, provide a quality attribute scenario with all six parts: source, stimulus, artefact, environment, response, and a measurable response measure."
    },
    {
      "id": "R2",
      "text": "Question 2: Recommend an architectural style for the next 12 months (for example, monolith, modular monolith, or microservices). Justify the recommendation with at least two trade-offs specific to CampusEats."
    },
    {
      "id": "R3",
      "text": "Question 3: Show your working. Calculate (a) order-placement availability using the component availabilities and independent failures, (b) expected order-placement downtime in hours per 30-day month, and (c) end-to-end availability and monthly downtime when a second independent payment provider of 99.5% availability is added active-active, with payment unavailable only when both providers are down."
    },
    {
      "id": "R4",
      "text": "Question 4: Name one architectural resilience pattern that could contain the slow-payment-provider failure. Explain how it works and would limit the outage, and state at least one drawback or tuning consideration."
    },
    {
      "id": "R5",
      "text": "Question 5: For menu browsing and for placing and paying for an order, choose whether to favour availability or consistency during a network partition. Justify each choice with reference to CAP theorem and name one concrete technique for each."
    },
    {
      "id": "R6",
      "text": "Question 6: Write a short ADR for introducing a message queue between order payment and outlet notification. Include Context, Decision, and Consequences, with at least one positive and one negative consequence."
    },
    {
      "id": "R7",
      "text": "State any assumptions made. Cite external sources in IEEE style and include the corresponding reference list; references do not count toward answer word limits."
    }
  ]
}
